// pRRTC's fk<Robot> launched the way pRRTC.cu launches it: 64 threads (4 per configuration) and
// 16 configurations per block, sphere positions and transforms in shared memory. Each block then
// writes its spheres out as (B, S, 3). Panda and Baxter are pRRTC's shipped headers; G1 is
// generated by cricket's gpu-cc-early-exit branch (see cricket_config/).
//
//   harness <panda|baxter|g1> <B> <q.f32> <out.f32> <K> <REPS> <WARMUP> [boxes.f32]
// prints the median over REPS of (time of K back-to-back launches) / K in ms. With a boxes
// file it runs FK + environment collision and writes one value per block of 16.

#include "src/planning/utils.cuh"
namespace ppln::robots {
#include "g1_struct.hh"
}
#include "src/robots/panda.cuh"
#include "src/robots/baxter.cuh"
namespace ppln::collision {
#include "g1.cuh"
}

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

template <class R, int NS, int NT>
__global__ void fk_kernel(const float* __restrict__ q, float* __restrict__ out, int B)
{
    __shared__ volatile float sphere_pos[NS * BATCH_SIZE * 3];
    __shared__ float T[BATCH_SIZE * NT * 16];
    const int tid = threadIdx.x;
    const int base = blockIdx.x * BATCH_SIZE;
    const int cfg = min(base + tid / 4, B - 1);
    float qq[R::dimension];
    for (int i = 0; i < R::dimension; ++i) qq[i] = q[cfg * R::dimension + i];
    ppln::collision::fk<R>(qq, sphere_pos, T, tid);
    __syncthreads();
    for (int i = tid; i < NS * BATCH_SIZE * 3; i += blockDim.x) {
        const int s = i / (BATCH_SIZE * 3), b = (i / 3) % BATCH_SIZE, c = i % 3;
        if (base + b < B) out[(size_t)(base + b) * NS * 3 + s * 3 + c] = sphere_pos[i];
    }
}

// fk<Robot> then env_collision_check<Robot> on every sphere (every joint gate set; pRRTC's
// templates index 20 gate slots per configuration, so the array is padded for g1's 44 joints).
// The check votes across the warp and stops at the first hit, and pRRTC.cu ORs it over the
// block: its answer is per block of BATCH_SIZE configurations (one edge), not per
// configuration. out[block] = 1 if any of the block's configurations is in collision.
template <class R, int NS, int NT>
__global__ void fkcc_kernel(const float* __restrict__ q, float* __restrict__ out, int B,
                            ppln::collision::Environment<float>* env)
{
    __shared__ volatile float sphere_pos[NS * BATCH_SIZE * 3];
    __shared__ float T[BATCH_SIZE * NT * 16];
    __shared__ volatile int gate[20 * BATCH_SIZE + 64];
    const int tid = threadIdx.x;
    for (int i = tid; i < 20 * BATCH_SIZE + 64; i += blockDim.x) gate[i] = 1;
    const int base = blockIdx.x * BATCH_SIZE;
    const int cfg = min(base + tid / 4, B - 1);
    float qq[R::dimension];
    for (int i = 0; i < R::dimension; ++i) qq[i] = q[cfg * R::dimension + i];
    __syncthreads();
    ppln::collision::fk<R>(qq, sphere_pos, T, tid);
    __syncthreads();
    const bool free_ = ppln::collision::env_collision_check<R>(sphere_pos, gate, env, tid);
    const int any = __syncthreads_or(!free_);
    if (tid == 0) out[blockIdx.x] = any ? 1.f : 0.f;
}

ppln::collision::Environment<float>* device_env(const char* path)
{
    // boxes file: M rows of 15 floats (centre, 3 unit axes, 3 half-extents)
    std::vector<float> raw;
    FILE* f = fopen(path, "rb");
    float v;
    while (f && fread(&v, sizeof(float), 1, f) == 1) raw.push_back(v);
    if (f) fclose(f);
    const unsigned m = raw.size() / 15;
    std::vector<ppln::collision::Cuboid<float>> boxes;
    for (unsigned i = 0; i < m; ++i) {
        const float* r = &raw[15 * i];
        boxes.emplace_back(r[0], r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9], r[10], r[11],
                           r[12], r[13], r[14]);
    }
    // as pRRTC.cu builds its device environment: a zeroed struct, then pointer and count
    ppln::collision::Environment<float>* d_env;
    cudaMalloc(&d_env, sizeof(*d_env));
    cudaMemset(d_env, 0, sizeof(*d_env));
    ppln::collision::Cuboid<float>* d_boxes;
    cudaMalloc(&d_boxes, sizeof(ppln::collision::Cuboid<float>) * m);
    cudaMemcpy(d_boxes, boxes.data(), sizeof(ppln::collision::Cuboid<float>) * m, cudaMemcpyHostToDevice);
    cudaMemcpy(&d_env->cuboids, &d_boxes, sizeof(d_boxes), cudaMemcpyHostToDevice);
    cudaMemcpy(&d_env->num_cuboids, &m, sizeof(m), cudaMemcpyHostToDevice);
    return d_env;
}

template <class R, int NS, int NT>
int run(int B, const char* qpath, const char* opath, int K, int REPS, int WARMUP, const char* envpath)
{
    const size_t per = envpath ? 1 : (size_t)NS * 3;
    std::vector<float> q((size_t)B * R::dimension), out((size_t)B * per);
    FILE* f = fopen(qpath, "rb");
    if (!f || fread(q.data(), sizeof(float), q.size(), f) != q.size()) return 1;
    fclose(f);
    float *dq, *dout;
    cudaMalloc(&dq, q.size() * sizeof(float));
    cudaMalloc(&dout, out.size() * sizeof(float));
    cudaMemcpy(dq, q.data(), q.size() * sizeof(float), cudaMemcpyHostToDevice);
    const int blocks = (B + BATCH_SIZE - 1) / BATCH_SIZE;
    ppln::collision::Environment<float>* env = envpath ? device_env(envpath) : nullptr;
    auto launch = [&] {
        if (env) fkcc_kernel<R, NS, NT><<<blocks, BATCH_SIZE * 4>>>(dq, dout, B, env);
        else fk_kernel<R, NS, NT><<<blocks, BATCH_SIZE * 4>>>(dq, dout, B);
    };
    for (int i = 0; i < WARMUP; ++i) launch();
    cudaDeviceSynchronize();
    cudaEvent_t a, b;
    cudaEventCreate(&a);
    cudaEventCreate(&b);
    std::vector<float> times;
    for (int r = 0; r < REPS; ++r) {
        cudaEventRecord(a);
        for (int k = 0; k < K; ++k) launch();
        cudaEventRecord(b);
        cudaEventSynchronize(b);
        float ms;
        cudaEventElapsedTime(&ms, a, b);
        times.push_back(ms / K);
    }
    if (cudaGetLastError() != cudaSuccess) return 2;
    cudaMemcpy(out.data(), dout, out.size() * sizeof(float), cudaMemcpyDeviceToHost);
    f = fopen(opath, "wb");
    fwrite(out.data(), sizeof(float), out.size(), f);
    fclose(f);
    std::nth_element(times.begin(), times.begin() + REPS / 2, times.end());
    printf("%.6f\n", times[REPS / 2]);
    return 0;
}

int main(int argc, char** argv)
{
    if (argc != 8 && argc != 9) return 3;
    const int B = atoi(argv[2]), K = atoi(argv[5]), REPS = atoi(argv[6]), W = atoi(argv[7]);
    const char* env = argc == 9 ? argv[8] : nullptr;
    if (!strcmp(argv[1], "panda")) return run<ppln::robots::Panda, PANDA_SPHERE_COUNT, 1>(B, argv[3], argv[4], K, REPS, W, env);
    if (!strcmp(argv[1], "baxter")) return run<ppln::robots::Baxter, BAXTER_SPHERE_COUNT, 2>(B, argv[3], argv[4], K, REPS, W, env);
    if (!strcmp(argv[1], "g1")) return run<ppln::robots::G1, G1_SPHERE_COUNT, 5>(B, argv[3], argv[4], K, REPS, W, env);
    return 3;
}
